/* cppi::a0c294a562dea1a72fce8c5c0e7bcdb7fe7ae3ccda2b6f9211824bb0f2929f96 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-12' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::9e20c5b48a9948debc8da47b918d3a59b2c4ade467a19d015f4ddc574763f37d */
select business_date as date_, security_id, 'SP500_20' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-12' and weight_ndo>0 and id_cppib_index = 'SP500_20_GR_USD_0_0' and security_id is not null

